import { DomainError } from "./DomainError";
import { TaskStatus } from "./TaskStatus";

export interface NewTask {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate: Date | null;
  status: TaskStatus;
}

export class Task {
  private currentStatus: TaskStatus;
  private currentAssigneeId: string | null = null;

  private constructor(
    readonly id: string,
    readonly projectId: string,
    readonly title: string,
    readonly description: string,
    readonly dueDate: Date | null,
    status: TaskStatus,
  ) {
    this.currentStatus = status;
  }

  static create(props: NewTask): Task {
    const title = props.title.trim();
    if (title.length === 0) {
      throw DomainError.validation("task title must not be empty");
    }
    return new Task(
      props.id,
      props.projectId,
      title,
      props.description,
      props.dueDate,
      props.status,
    );
  }

  get status(): TaskStatus {
    return this.currentStatus;
  }

  get assigneeId(): string | null {
    return this.currentAssigneeId;
  }

  assignTo(userId: string): void {
    this.currentAssigneeId = userId;
  }

  markDone(): void {
    if (this.currentStatus === "done") {
      throw DomainError.conflict(`task ${this.id} is already done`);
    }
    this.currentStatus = "done";
  }
}

